INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14795$nota-0097$m14795$, $m14796$Training and Racing with a Power Meter.pdf$m14796$, $m14797$272$m14797$, $m14798$we notice Neuromuscular/Level 7 power falls below 'novice' until he reaches 1 minute... His focus is completely on triathlon, so even though this might be a weakness, it doesn't make sense to try and improve it or even spend time training at Level 7. His training time is better spent elsewhere, like FTP.$m14798$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14799$nota-0097$m14799$, $m14800$nota-0082$m14800$, $m14801$pre-requisito$m14801$, $m14802$usa o Mapa Fenotípico/Power Profile (nota-0082, Cap.8) para identificar pontos fracos, mas filtra quais deles merecem ser treinados conforme a modalidade-alvo$m14802$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14803$nota-0117$m14803$, $m14804$Training and Racing with a Power Meter.pdf$m14804$, $m14805$327$m14805$, $m14806$Most triathletes do not understand how easy it is to ride too fast on the bike leg; it's the number one cause of DNFs in triathlons. The difference between a well-paced bike leg and a poorly paced one can be as little as 15 watts (normalized) for an average in the event.$m14806$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14807$nota-0117$m14807$, $m14808$nota-0111$m14808$, $m14809$complementa$m14809$, $m14810$reforça a importância prática de seguir a NP-alvo calculada pela fórmula do orçamento de TSS (nota-0111), já que pequenos excessos têm grande impacto$m14810$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14811$nota-0138$m14811$, $m14812$Training and Racing with a Power Meter.pdf$m14812$, $m14813$392$m14813$, $m14814$Power files of 24-hour racers have shown that putting out more wattage in the first four hours of a race and creating a gap on the competition can be a huge advantage later in the event. In an ultra race (a race longer than six hours), most athletes fatigue at the same rate over the next 18 hours, so a gap of 45 minutes from Rider 1 to Rider 2 at the six-hour mark is most likely going to hold for the next 18 hours.$m14814$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14815$nota-0138$m14815$, $m14816$Training and Racing with a Power Meter.pdf$m14816$, $m14817$396$m14817$, $m14818$the higher-than-average pacing that occurs in the first four hours can be the difference between winning and losing (especially so in a long 24-hour race), but races in the six- to eight-hour range are more competitive and similar to long road races, where the winning attacks come near the end of the event.$m14818$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14819$nota-0138$m14819$, $m14820$nota-0137$m14820$, $m14821$complementa$m14821$, $m14822$aplicação prática, em prova de 24h, do mesmo princípio de gap de distância descrito no Efeito Allen (nota-0137)$m14822$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14823$nota-0164$m14823$, $m14824$Manual treinamento.pdf$m14824$, $m14825$69$m14825$, $m14826$Atleta A: VO₂máx = 82 mL·kg⁻¹·min⁻¹, FTP = 300 W, excelente potência máxima, baixa economia. Atleta B: VO₂máx = 74 mL·kg⁻¹·min⁻¹, FTP = 340 W, excelente economia, maior resistência à fadiga. Quem possui maior probabilidade de vencer uma prova de estrada? Provavelmente o Atleta B.$m14826$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14827$nota-0164$m14827$, $m14828$nota-0163$m14828$, $m14829$complementa$m14829$, $m14830$reforça a advertência da nota-0163 de que a tabela de referência de VO2máx não deve ser usada para prever desempenho competitivo isoladamente$m14830$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14831$nota-0200$m14831$, $m14832$Manual treinamento.pdf$m14832$, $m14833$183$m14833$, $m14834$Os escaladores... normalmente possuem: elevada relação potência/peso; baixo percentual de gordura; excelente capacidade aeróbia; elevada economia metabólica; grande tolerância ao exercício prolongado.$m14834$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14835$nota-0200$m14835$, $m14836$Manual treinamento.pdf$m14836$, $m14837$184$m14837$, $m14838$O contrarrelogista... elevada potência absoluta; excelente capacidade de sustentar esforço contínuo; elevada eficiência aerodinâmica... O velocista depende principalmente de: potência neuromuscular; capacidade anaeróbia; elevada força máxima; rápida ativação muscular.$m14838$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14839$nota-0200$m14839$, $m14840$Manual treinamento.pdf$m14840$, $m14841$185$m14841$, $m14842$O especialista em clássicas... elevada resistência aeróbia; excelente durabilidade; boa potência anaeróbia; capacidade de recuperação após esforços repetidos... É um dos perfis fisiológicos mais completos do ciclismo.$m14842$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14843$nota-0200$m14843$, $m14844$Manual treinamento.pdf$m14844$, $m14845$185$m14845$, $m14846$O MTB caracteriza-se por mudanças constantes de intensidade... elevado VO₂máx; excelente capacidade anaeróbia; rápida recuperação entre esforços; técnica refinada... O ultraciclista... excepcional resistência aeróbia; elevada durabilidade; eficiência metabólica; excelente utilização de gordura; estabilidade psicológica.$m14846$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14847$nota-0200$m14847$, $m14848$nota-0082$m14848$, $m14849$complementa$m14849$, $m14850$descrição narrativa/qualitativa de arquétipos por especialidade, complementar ao Mapa Fenotípico quantitativo baseado em Pmax/FTP/FRC já registrado na nota-0082 do Livro 1$m14850$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14851$nota-0207$m14851$, $m14852$VO2 Max Essentials_Final.pdf$m14852$, $m14853$12$m14853$, $m14854$Up until about age 30, VO2 max can increase a fair amount, assuming you're physically active and not a couch potato. But around age 30 to 40, we begin to see a somewhat linear decline in our aerobic capacity. The importance here may be that the more you increase your VO2 max while you're young, the higher 'baseline' you'll have once aerobic capacity inevitably begins to decline.$m14854$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m14855$nota-0207$m14855$, $m14856$VO2 Max Essentials_Final.pdf$m14856$, $m14857$13$m14857$, $m14858$Data show that even among exercise-trained or physically-active older adults, VO2 max still declines... there is a consistently observed and linear decline in VO2 max throughout life no matter how active you are.$m14858$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m14859$nota-0207$m14859$, $m14860$nota-0036$m14860$, $m14861$complementa$m14861$, $m14862$fornece o mecanismo fisiológico (declínio linear de VO2máx pós-30/40 anos) por trás da limitação do Power Profile por idade já registrada na nota-0036 do Livro 1$m14862$)
